const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { tier: 'Warm', reasoning: 'parse_error - defaulted to Warm for human review', _parse_error: true }; }
const base = $('Parse Ingestion Output').first().json;
return [{ json: { ...base, ...parsed } }];

// Lightweight retrieval: keyword match on category/product_interest + budget filter.
// In production this is a vector-similarity lookup (see Technical Design Doc §4);
// this deterministic version keeps the reference build runnable without a vector DB.
const rows = $input.all().map(i => i.json);
const lead = $('Parse Qualifier Output').first().json;
const budget = lead.per_unit_budget || lead.budget_total || null;
const interest = (lead.product_interest || lead.category_hint || '').toLowerCase();

const scored = rows.map(r => {
  const hay = `${r.name} ${r.category} ${r.description}`.toLowerCase();
  let score = 0;
  interest.split(/\W+/).forEach(w => { if (w.length > 2 && hay.includes(w)) score += 2; });
  const price = parseFloat(r.price);
  const withinBudget = budget ? price <= Number(budget) : true;
  return { ...r, _score: score, _within_budget: withinBudget };
}).filter(r => r._within_budget)
  .sort((a,b) => b._score - a._score)
  .slice(0, 5);

return [{ json: { ...lead, catalog_context: JSON.stringify(scored), catalog_sku_list: scored.map(s => s.name) } }];

const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { recommendations: [], no_match_reason: 'parse_error', _parse_error: true }; }
const base = $('Retrieve & Rank Catalog Matches (RAG-lite)').first().json;
return [{ json: { ...base, ...parsed } }];

// Hard gate: every recommended sku_or_name MUST string-match a row we actually retrieved
// from the live catalog sheet. This is what makes the "never invent a product" rule
// enforceable rather than just a prompt instruction (Technical Design Doc §3, Layer 3).
const item = $input.first().json;
const allowed = new Set((item.catalog_sku_list || []).map(s => String(s).toLowerCase().trim()));
const recs = item.recommendations || [];
const invalid = recs.filter(r => !allowed.has(String(r.sku_or_name).toLowerCase().trim()));
const validation_passed = invalid.length === 0;
return [{ json: { ...item, validation_passed, invalid_recommendations: invalid } }];

const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
