const base = $('Catalog Validator (Deterministic)').first().json;
return [{ json: { ...base, draft_subject: parsed.subject, draft_body: parsed.body } }];

const rows = $input.all().map(i => i.json);
const q = ($('Normalize Email Input').first().json.email_body || '').toLowerCase();
const scored = rows.map(r => {
  const hay = `${r.name} ${r.category} ${r.description}`.toLowerCase();
  let score = 0;
  q.split(/\W+/).forEach(w => { if (w.length > 2 && hay.includes(w)) score++; });
  return { ...r, _score: score };
}).sort((a,b) => b._score - a._score).slice(0, 5);
const base = $('Normalize Email Input').first().json;
return [{ json: { ...base, catalog_context: JSON.stringify(scored) } }];

