const x = $input.first().json; 
const now = new Date(); 
const id = 'CMP-' + now.toISOString().replace(/[-:TZ.]/g, '').slice(0, 14) + '-' + Math.floor(Math.random() * 9000 + 1000);

// Regex to separate "Name <email@domain.com>" from the x["From"] string
const fromString = x["From"] || '';
const nameMatch = fromString.match(/^([^<]+)/);
const emailMatch = fromString.match(/<([^>]+)>/);

const customer_name = nameMatch ? nameMatch[1].trim() : '';
const customer_email = emailMatch ? emailMatch[1].trim() : fromString;

// Regex to extract the order ID (e.g., ORD-45872) from the text/snippet
const snippetText = x.textPlain || x.text || x.snippet || '';
const orderMatch = snippetText.match(/ORD-\d+/i);
const order_id = orderMatch ? orderMatch[0] : '';
const pur_amt= snippetText.match(/amount-\d+/i);
const add_info= snippetText.match(/details-\d+/i) || snippetText.match(/info-\d+/i) ;

return [{
  json: {
    complaint_id: id,
    customer_name: customer_name,
    customer_email: customer_email,
    subject: x["Subject"] || x.subject || '',
    complaint_text: snippetText,
    message_id: x.id || x.messageId || '',
    order_id: order_id,
    purchase_amount: pur_amt,
    additional_information: add_info
  }
}];

