const j = $input.first().json;
const exec = j.execution || {};
const err = exec.error || {};
// n8n Code-node errors split the thrown message on colons across message/description;
// the stack keeps the original string, so search all three for the LEAD/TRACE tags.
const hay = [err.message, err.description, err.stack].filter(Boolean).join(" | ");
const leadM = hay.match(/LEAD:([A-Za-z0-9_-]+)/);
const traceM = hay.match(/TRACE:([A-Za-z0-9_-]+)/);
return [{ json: {
  workflow_name: (j.workflow || {}).name || "unknown",
  workflow_id: (j.workflow || {}).id || null,
  execution_id: exec.id || null,
  execution_url: exec.url || null,
  failed_node: exec.lastNodeExecuted || (err.node || {}).name || null,
  message: hay.slice(0, 500) || "unknown error",
  lead_id: leadM ? leadM[1] : "",
  trace_id: traceM ? traceM[1] : null,
  happened_at: new Date().toISOString()
} }];

const lf = String.fromCharCode(10);
const now = Date.now();
const weekAgo = now - 7 * 24 * 60 * 60 * 1000;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const recent = rows.filter(r => {
  const t = Date.parse(r.timestamp);
  return !isNaN(t) && t >= weekAgo && t <= now;
});
const windowLabel = new Date(weekAgo).toISOString().slice(0, 10) + " to " + new Date(now).toISOString().slice(0, 10);

if (recent.length === 0) {
  const body = "SalesGenie Weekly Insights (" + windowLabel + ")" + lf + lf +
    "No inbound inquiries were processed this week." + lf +
    "No leads to report.";
  return [{ json: { has_activity: false, subject: "SalesGenie Weekly Insights - No activity (" + windowLabel + ")", report: body } }];
}

const norm = (s) => (s == null ? "" : String(s)).trim().toLowerCase();
let hot = 0, warm = 0, cold = 0, approved = 0, rejected = 0, other = 0;
const productCounts = {};
for (const r of recent) {
  const score = norm(r.lead_score);
  if (score === "hot") hot++;
  else if (score === "warm") warm++;
  else if (score === "cold") cold++;
  const st = norm(r.status);
  if (st === "approved") approved++;
  else if (st === "rejected") rejected++;
  else other++;
  const rec = (r.recommendations == null ? "" : String(r.recommendations));
  const products = rec.split(lf).map(x => x.split(" - ")[0].trim()).filter(x => x);
  for (const p of products) {
    productCounts[p] = (productCounts[p] || 0) + 1;
  }
}
const topProducts = Object.keys(productCounts)
  .map(k => ({ product: k, count: productCounts[k] }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 5);
const topProductsText = topProducts.length
  ? topProducts.map(p => "  - " + p.product + " (" + p.count + ")").join(lf)
  : "  - None";

const total = recent.length;
const pct = (n) => total ? Math.round((n / total) * 100) : 0;

const body = "SalesGenie Weekly Insights (" + windowLabel + ")" + lf + lf +
  "Total inquiries processed: " + total + lf + lf +
  "Lead scoring:" + lf +
  "  - Hot:  " + hot + " (" + pct(hot) + "%)" + lf +
  "  - Warm: " + warm + " (" + pct(warm) + "%)" + lf +
  "  - Cold: " + cold + " (" + pct(cold) + "%)" + lf + lf +
  "Approval outcomes:" + lf +
  "  - Approved: " + approved + lf +
  "  - Rejected: " + rejected + lf +
  (other ? "  - Other/pending: " + other + lf : "") + lf +
  "Top recommended products:" + lf + topProductsText + lf;

return [{ json: {
  has_activity: true,
  subject: "SalesGenie Weekly Insights - " + total + " leads (" + windowLabel + ")",
  report: body,
  total: total, hot: hot, warm: warm, cold: cold,
  approved: approved, rejected: rejected,
  top_products: topProducts
} }];
